                    raise AgentError('PROVIDER_EMPTY_RESPONSE', '供应商完成信号未包含正文；保留记录并尝试备用模型')
                if not self.active():
                    raise AgentError('CANCELLED', '取消后的 API 响应已丢弃，不发布')
                complete = True
                return
